 "content": "from collections import deque


def transform(grid):
    """Fill each hollow rectangular colored frame by interior-size parity."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = all(
                grid[y][x] == color
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            )
            if not perimeter:
                continue
            # Odd-sized interiors become 7; even-sized interiors become 2.
            inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
            fill = 7 if (inner_h * inner_w) % 2 else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == background:
                        out[y][x] = fill
    return out
